SKU ALI-AB52-LA-D

As part of the Alibi Vigilant Series, this 5MP 4-in-1 Fixed Bulllet Security Camera delivers crisp video day or night, providing HD-TVI/AHD/CVI/CVBS output for compatibility. Connect to any analog cameras on your network with one easy solution.

Protecting your home or business has never been easier – or more convenient. The 5MP HD-TVI bullet security camera offers an impressive 131 feet, perfect for after-hours surveillance or anywhere you need to capture bright footage in dark conditions to protect your business. Whether it’s 12pm or 12am, this versatile indoor/outdoor camera provides clear, crisp surveillance.

A 2.8mm wide-angle lens and Up the Coax (UTC) technology enables you to control the camera’s onscreen display (OSD) from your web browser and the Alibi CMS or smartphone app.

**Multi-Megapixel Resolution Video –** 5MP resolution allows you to capture a high level of clarity and detail for most applications

**IP67 weatherproof housing** –this camera can handle long-term durability even among extreme weather conditions such as rain, snow, and ice.

**IllumiNite Technology featuring Starlight chipsets** – features an HD progressive scan CMOS sensor, capturing clear and vivid color images day or night – even in extremely dark environments.

**Multi-megapixel resolution – Get more detail from your video camera.** This camera captures high-resolution video footage that delivers crisp, precise detail and clarity for your video security needs.

**Innovative Day/Night Scene Detection** – includes a hardware sensor for smart software imaging that detects surveillance scene illumination. Designed to be water and dust-proof, this allows you to avoid unexpected costs of hardware failure.

**Intuitive interface – everything you need to manage your system at your fingertips.** With an intuitive interface and access to the free Alibi CMS and mobile app, system management has never been simpler.

**What’s Included**

