Protecting your home or business has never been easier – or more convenient. The 2MP HD-TVI dome security camera offers an impressive 98 feet IR – perfect for after-hours surveillance or anywhere you need to capture bright footage in dark conditions to protect your business. Whether it’s 12pm or 12am, this versatile indoor/outdoor camera provides clear, crisp surveillance.

