SKU ALI-AT22-UA-D

As part of the Alibi Vigilant Series, this 2MP 4-in-1 Fixed Turret Security Camera delivers crisp video day or night, providing HD-TVI/AHD/CVI/CVBS output for compatibility. Connect to any analog cameras on your network with one easy solution.

Protecting your home or business has never been easier – or more convenient. The 2MP HD-TVI turret security camera offers an impressive 131 feet IR – perfect for after-hours surveillance or anywhere you need to capture bright footage in dark conditions to protect your business. Whether it’s 12pm or 12am, this versatile indoor/outdoor camera provides clear, crisp surveillance.

A 2.8mm wide-angle lens and Up the Coax (UTC) technology enables you to control the camera’s onscreen display (OSD) from your web browser and the Alibi CMS or smartphone app.

**Multi-Megapixel Resolution Video –** 2MP resolution allows you to capture a high level of clarity and detail for most applications

**IP67 weatherproof housing** –this camera can handle long-term durability even among extreme weather conditions such as rain, snow, and ice.

**Multi-megapixel resolution – Get more detail from your video camera.** This camera captures high-resolution video footage that delivers crisp, precise detail and clarity for your video security needs.

**Full Frame Illumination with Smart IR** Smart full-frame illumination technology offers several advantages over standard IR for flawless night vision, including:

Clearer, brighter images in low light and at night
Reduces overexposure of the IR LEDs at the center of the image
Increases illuminant efficiency up to 30%
Produces LED light in rectangle form to better fit screen size
Captures images up to 131 feet in the dark without washing out the subject at closer ranges
Reduces video noise for a clearer nighttime picture and reduces bandwidth consumption and video storage requirements

**Innovative Day/Night Scene Detection** – includes a hardware sensor for smart software imaging that detects surveillance scene illumination. Designed to be water and dust-proof, this allows you to avoid unexpected costs of hardware failure.

**Intuitive interface – everything you need to manage your system at your fingertips.** With an intuitive interface and access to the free Alibi CMS and mobile app, system management has never been simpler.

**What’s Included**

2MP IP 131 feet IR fixed turret security camera
Mounting template
