SKU ALI-PB41-UAI-D

The Alibi Vigilant Performance Series, **4MP 262 feet IR Fixed Bullet Camera** delivers crisp video day or night. It also offers flexible storage solutions, with a built-in micro SD slot – enabling local storage up to 256GB.

**Multi-Megapixel Resolution Video –** 4MP resolution provides exceptional clarity and detail for most applications.
**IntelliSearchTM Color Match Technology -** Powerful camera analytics capture apparel colors and vehicle color and apply metadata to the video recording. Using powerful search algorithms, users can apply filters to quickly search for upper or lower garment color or vehicle exterior color significantly reducing the amount of time needed to search video footage.
**Smart Full-Frame IR = Better Video at Night** – Advanced full-frame illumination technology helps you capture up to 262 feet of nighttime video footage with more contrast and clarity.
**Co lor Attribute Collection –** Advanced technology collects the color information of the target with high accuracy for identification of a human’s upper and lower garment, color of a vehicle, and upper garment color of the driver of a non-motor vehicle.
**Auto Scene Adjustment (intelligent WDR) –** Allows camera to easily and quickly improve image quality in high-contrast lighting conditions (foggy, backlit, flickering) and capture details in both areas of the video that are dimly and brightly lit.
**SmartSense technology** – utilizes AI deep learning developed data algorithms to identify human and vehicular targets with extreme accuracy and reduce false alarms.
**Starlight 2.0 Chipset Technology –** featuring an HD progressive scan CMOS sensor, capturing clear and vivid color images day or night – even in extremely dark environments.
**Lower Bandwidth and Storage Usage** – Ultra H.265 Compression technology reduces the video stream''s overall requirements, saving you bandwidth and hard drive space.
**Easy management** –an intuitive interface and access to the free Vigilant Mobile App and Vigilant CMS makes management more straightforward than ever.

**Full Frame Illumination with Smart IR** Smart full-frame illumination technology offers several advantages over standard IR for flawless night vision, including:

Clearer, brighter images in low light and at night
Reduces overexposure of the IR LEDs at the center of the image
Increases illuminant efficiency up to 30%
Produces LED light in rectangle form to better fit screen size
Captures images up to 262 feet in the dark without washing out the subject at closer ranges
Reduces video noise for a clearer nighttime picture and reduces bandwidth consumption and video storage requirements

**HTML5 Plugin Free –** use on almost any Browser for support:

Plug-in required live view: IE9+, Chrome 41 and below, Firefox 52 and below
Plug-in free live view: Chrome 57.0+, Firefox 58.0+, Edge 16+, Safari 11+

**Ultra H.265 Compression – reduce bandwidth and storage requirements.** With Ultra H.265 compression technology, you can store more information using less hard drive space. Ultra H.265 also helps you minimize bandwidth requirements for high-resolution video and makes the remote viewing less demanding on the recorder.

**Intuitive interface – everything you need to manage your system at your fingertips.** With an intuitive interface and access to the free Vigilant Mobile App and Vigilant CMS, system management has never been simpler.

**What’s Included:**

(1) Alibi Vigilant Performance Series 4MP IP bullet security camera
(1) Mounting template
(1) Mounting hardware
(1) Quick start guide

**IP67 weatherproof housing -** this bullet camera delivers long-term durability even among extreme weather conditions such as rain, snow, and ice and has a wide temperature range of -22 degrees to 140 degrees Fahrenheit.

**Protection and Warranty:**

