SKU ALI-PD80-VUAI-D

The Alibi Vigilant Performance Series security camera delivers high-resolution video capture and has been specifically designed and manufactured to comply with the latest technical requirements specified under NDAA regulations.

**Multi-megapixel resolution – get more detail from your video camera –** 8MP camera captures crisp, high definition video at day and night **.** This camera captures multi-megapixel resolution video footage that delivers crisp, clear detail and clarity for your video security needs.

**IntelliSearch Color Match Technology -** Powerful camera analytics capture apparel colors and vehicle color and apply metadata to the video recording. Using powerful search algorithms, users can apply filters to quickly search for upper or lower garment color or vehicle exterior color significantly reducing the amount of time needed to search video footage

**Capture Color Video in Low Light Conditions –** Starlight technology chipset uses ambient light sources to capture color videos in extreme low light conditions.

**Smart Analytics Included -** this camera is equipped with state-of-the-art analytics to help you setup event-based triggers and alerts so your security solution is effective and smart. Analytics include:

Motion
Tampering
Intrusion
Cross Line
Enter/Leave Area
Audio Detection

**Full Frame Illumination with Smart IR –** Smart full-frame illumination technology offers several advantages over standard IR for flawless night vision, including:

Clearer, brighter images in low light and at night
Delivers a wider illumination spread
Unique rectangular IR LED design produces a uniformly illuminated image across the entire screen
Reduces overexposure at the center of the image and eliminates hot spots
Eliminates blooming from lights by reducing ambient light pollution
Reduces video noise for a clearer nighttime picture, and reduces bandwidth consumption and video storage requirements

**IP67 Rated for Superior Outdoor Performance** – With an IP67 weather-rated metal enclosure, this camera has a wide temperature range of -22 degrees to 140 degrees Fahreneheit – offering long-term durability even among extreme weather conditions such as rain, snow, and ice.

**3D Digital Noise Reduction (DNR**) effectively filters noise to produce a more crisp, clear video stream.

**IK10** vandalproof rating for tamper-proof installations

**Ultra H.265 Compression – reduce bandwidth and storage requirements.** Capture more information using less hard drive space. Ultra H.265 also helps you minimize bandwidth requirements for high-resolution video and makes remote viewing less demanding on the recorder.

**HTML5 Plugin Free –** use on almost any Browser for support:

Plug-in required live view: IE9+, Chrome 41 and below, Firefox 52 and below
Plug-in free live view: Chrome 57.0+, Firefox 58.0+, Edge 16+, Safari 11+

**Intuitive interface – everything you need to manage your system at your fingertips.** With an intuitive interface, along with access to the free Vigilant Mobile App and Viligant CMS, system management has never been simpler.

**What’s Included:**

(1) 8MP IP security camera
(1) Mounting template
(1) Mounting hardware
(1) Quick start guide

**Protection and Warranty:**

