SKU ALI-PZ51-LUZAIS-D

The Alibi Vigilant Performance Series 5MP Mini-PTZ security camera delivers high-resolution and has been specifically designed and manufactured to comply with the latest technical requirements specified under NDAA regulations.

This security camera delivers crisp video day or night. This high-resolution dome camera offers several viewing-angle options, Starlight technology, and night vision at 164 feet.

**Small Size, Big Performance -** the compact design of this mini-PTZ makes it easier to install in a variety of situations while still providing high-resolution video capture with flexible FOV options.

**Capture Color Video at Night –** Starlight technology chipset uses ambient light sources to capture color video in extreme low light conditions. In the darkness, you can rely on the camera’s full-frame illumination technology to see clear, sharp images in the dark.

**3D Digital Noise Reduction (DNR)** – Get exceptional video image quality with less noise. 3D Digital Noise Reduction (3D-DNR). 3D-DNR incorporates frame-to-frame noise reduction with spatial noise reduction to produce clear video images with less noise in low light conditions.

**IP66 weatherproof housing** - delivering long-term durability even among extreme weather conditions such as rain, snow, and ice and has a wide temperature range of -40 degrees to 149 degrees Fahrenheit.

**Key Features and Capabilities:**

**Multi-megapixel resolution – Get more detail from your video camera.** This camera captures multi-megapixel resolution video footage that delivers crisp, precise detail and clarity for your video security needs.

**Starlight 2.0 Chipset Technology –** featuring an HD progressive scan CMOS sensor, this next generation Starlight chipset can capture clear and vivid color images day or night – even in extremely dark environments.

**Innovative Day/Night Scene Detection** – includes a hardware sensor for smart software imaging that detects surveillance scene illumination. Designed to be water and dust-proof, this allows you to avoid unexpected costs of hardware failure.

**HTML5 Plugin Free –** use on almost any Browser for support:

Plug-in required live view: IE9+, Chrome 41 and below, Firefox 52 and below
Plug-in free live view: Chrome 57.0+, Firefox 58.0+, Edge 16+, Safari 11+

**Ultra H.265 Compression – reduce bandwidth and storage requirements.** With Ultra H.265 compression technology, you can store more information using less hard drive space. Ultra H.265 also helps you minimize bandwidth requirements for high-resolution video and makes the remote viewing less demanding on the recorder.

**Intuitive interface – everything you need to manage your system at your fingertips.** With an intuitive interface and access to the free Vigilant Mobile App and Viligant CMS, system management has never been simpler.

**SmartSense technology** – utilizes AI deep learning developed data algorithms to identify human and vehicular targets with extreme accuracy and reduce false alarms.

**What’s Included:**

(1) Alibi Vigilant Performance Series 5mp Starlight IP PTZ dome security camera
(1) Mounting template
(1) Mounting hardware
(1) Quick start guide

**Protection and Warranty:**

