INSERT OR IGNORE INTO products (slug,name,brand,brand_slug,category,price_cents,msrp_cents,cost_cents,blurb,image,featured,stock,stock_tracked,active,specs,meta_title,meta_description,meta_keywords,gtin,mpn,highlights,badges,options,addon) VALUES ('ali-xf120-vai-d','Alibi ALI-XF120-VAI-D Vigilant Performance Series 12MP IP Vandal-Resistant Fisheye Fixed Dome Camera','ALIBI','alibi','security-ip-cameras',132999,139999,NULL,'**Alibi Vigilant Performance Series 12MP IP Vandal-Resistant Fisheye Fixed Dome Camera**
SKU ALI-XF120-VAI-D

The Alibi Vigilant Performance Series, 12MP Vandal-Resistant Fisheye Dome Security Camera delivers crisp video day or night. Designed for indoor and outdoor use, this ultra-high-resolution fisheye dome camera goes the distance by providing an ultra-wide 360 degrees lens, and protects against extreme weather conditions and vandalism with an IP67 and IK10 rating.

**Multi-Megapixel Resolution Video –** 12MP camera captures a high level of clarity and detail for most applications

**3D Digital Noise Reduction (DNR**) – Get exceptional video image quality with less noise. 3D Digital Noise Reduction (3D-DNR). 3D-DNR incorporates frame-to-frame noise reduction with spatial noise reduction to produce clear video images with less noise in low light conditions.

**Smart Analytics** includes:

Motion Detection
Intrusion Detection
Cross line Detection
Tampering Alarm
Audio Detection
Heat Map

**IP67 weatherproof housing** this dome camera has a wide temperature range of -31 degrees to 140 degrees Fahrenheit – delivering long-term durability even among extreme weather conditions such as rain, snow, and ice.

**Key Features and Capabilities**

**Multi-megapixel resolution – Get more detail from your video camera.** This camera captures multi-megapixel resolution video footage with 360 degrees panoramic lens that delivers crisp, precise detail and clarity for your video security needs.

**IK10 vandal-resistant – durable design for around-the-clock surveillance.** Built for high resistance to impact, the metal-encased design of this vandal dome camera is unmatched by anything on the market –making it a safe and secure camera for years to come.

**Smart Full-Frame IR - Night vision that goes the distance.** Smart full-frame illumination technology offers several advantages over standard IR for flawless night vision, including:

Clearer, brighter images in low light and at night
Reduces overexposure of the IR LEDs at the center of the image
Increases illuminant efficiency up to 30%
Produces LED light in rectangle form to better fit screen size
Captures images up to 49 feet in the dark without washing out the subject at closer ranges
Reduces video noise for a clearer nighttime picture, and reduces bandwidth consumption and video storage requirements

**Onboard Storage Options –** This camera gives you storage flexibility with an onboard SD slot that supports up to 256GB

**Innovative Day/Night Scene Detection** – includes a hardware sensor for smart software imaging that detects surveillance scene illumination. Designed to be water and dust-proof, this allows you to avoid unexpected costs of hardware failure.

**Ultra H.265 Compression – reduce bandwidth and storage requirements.** With Ultra H.265 compression technology, you can store more information using less hard drive space. Ultra H.265 also helps you minimize bandwidth requirements for high-resolution video and makes remote viewing less demanding on the recorder.

**Intuitive interface – everything you need to manage your system at your fingertips.** With an intuitive interface, along with access to the free Vigilant Mobile App and Vigilant CMS, system management has never been simpler.

**What’s Included:**

12-megapixel IP fisheye dome security camera
Mounting template
Mounting Screws (4)
Quick start guide
Weatherproof Connector

**Protection and Warranty:**

Covered by Alibi''s 3-Year Warranty on the camera and recorder hardware and components, with unlimited US-based technical support. Questions before or after you buy? Call the shop and we will help you choose and set it up.','/img/alibi/ali-xf120-vai-d-1.jpg',0,0,0,1,'Audio	Yes
