SKU ALI-XT81-UZAI-D

The Alibi Vigilant Performance Series, 8MP Varifocal Eyeball Turret IP Security Camera delivers crisp video day or night. Featuring **Starlight 2.0 Chipset Technology,** this powerful camera captures clear and vivid color images day or night – even in extremely dark environments.

It also offers flexible storage solutions, with a built-in micro SD slot – enabling local storage up to 256GB and includes a built-in mic for powerful audio surveillance.

**Motorized Varifocal Lens** - 2.8 – 12 mm autofocus motorized zoom lens

**3D Digital Noise Reduction (DNR)** effectively filters noise to produce a more crisp, clear video stream.

**IP67 weatherproof housing** this bullet camera delivers long-term durability even among extreme weather conditions such as rain, snow, and ice and has a wide temperature range of -22 degrees to 140 degrees Fahrenheit.

**Key Features and Capabilities**

**Multi-megapixel resolution – Get more detail from your video camera.** This camera captures 8MP resolution video footage that delivers crisp, precise detail and clarity for your video security needs.

**Starlight 2.0 Chipset Technology –** featuring an HD progressive scan CMOS sensor, capturing clear and vivid color images day or night – even in extremely dark environments.

**SmartSense technology** – utilizes AI deep learning developed data algorithms to identify human and vehicular targets with extreme accuracy and reduce false alarms.

**IK10 vandal-resistant – durable design for around-the-clock surveillance.** Built for high resistance to impact, this vandal dome camera''s metal-encased design is unmatched by anything on the market –making it a safe and secure camera for years to come.

**Smart Full-Frame IR - Night vision that goes the distance.** Smart full-frame illumination technology offers several advantages over standard IR for flawless night vision, including:

Clearer, brighter images in low light and at night
Reduces overexposure of the IR LEDs at the center of the image
Increases illuminant efficiency up to 30%
Produces LED light in rectangle form to better fit screen size
Captures images up to 131′ in the dark without washing out the subject at closer ranges
Reduces video noise for a clearer nighttime picture and reduces bandwidth consumption and video storage requirements

**Innovative Day/Night Scene Detection** – includes a hardware sensor for smart software imaging that detects surveillance scene illumination. Designed to be water and dust-proof, this allows you to avoid unexpected costs of hardware failure.

**HTML5 Plugin Free –** use on almost any Browser for support:

Plug-in required live view: IE9+, Chrome 41 and below, Firefox 52 and below
Plug-in free live view: Chrome 57.0+, Firefox 58.0+, Edge 16+, Safari 11+

**Ultra H.265 Compression – reduce bandwidth and storage requirements.** With Ultra H.265 compression technology, you can store more information using less hard drive space. Ultra H.265 also helps you minimize bandwidth requirements for high-resolution video and makes the remote viewing less demanding on the recorder.

**Intuitive interface – everything you need to manage your system at your fingertips.** With an intuitive interface and access to the free Vigilant Mobile App and Vigilant CMS, system management has never been simpler.

**What’s Included:**

(1) Alibi Vigilant Performance Series 8MP varifocal vandal-resistant turret IP security camera
(1) Mounting template
(1) Mounting hardware
(1) Quick start guide

**Protection and Warranty:**

